"""Real JEE Main questions — Chemistry Unit 15: Hydrocarbons. Our own solutions; chk recomputes what can be computed —
combustion stoichiometry, masses from formulae, stereoisomers and chirality of products from their structures
(orgkit.py), hydrogen types — and checks reaction outcomes against a fact table of NCERT hydrocarbon reactions."""
import re
from common import new_registry, pick, verify
from chemkit import stmt, pickset
from orgkit import Mol
P, add = new_registry()
AM = {'C': 12, 'H': 1, 'N': 14, 'O': 16, 'Br': 80, 'Cl': 35.5}
def mm(f): return sum(AM[e] * (int(n) if n else 1) for e, n in re.findall(r'([A-Z][a-z]?)(\d*)', f))
STO = ['Both Statement I and Statement II are true', 'Both Statement I and Statement II are false', 'Statement I is true but Statement II is false', 'Statement I is false but Statement II is true']
STC = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct']
def o2_alkane(n): return (3 * n + 1) / 2
def primary(s): m = Mol(s); return sum(1 for i, e in enumerate(m.a) if e == 'C' and len(m.nb[i]) == 1)
def sec_h(s): m = Mol(s); return sum(m.h[i] for i, e in enumerate(m.a) if e == 'C' and len(m.nb[i]) == 2)
# directing/activating effect of groups in EAS
DIR = {'CH3': ('op', 1), 'NHCOCH3': ('op', 1), 'OH': ('op', 2), 'NH2': ('op', 2), 'Cl': ('op', -1), 'NO2': ('m', -2), 'COCH3': ('m', -1), 'COOH': ('m', -1)}

